package healer
import("encoding/json";"errors";"os";"path/filepath";"strings";"revela-worldwide.local/libs/country")
type Pattern struct{ID string `json:"id"`;Category string `json:"category"`;MatchAny []string `json:"match_any"`;Recommendation string `json:"recommendation"`;Risk string `json:"risk"`}
type failureDB struct{Patterns []Pattern `json:"patterns"`}
type Result struct{Country country.Profile `json:"country_context"`;Matched bool `json:"matched"`;PatternID string `json:"pattern_id,omitempty"`;Category string `json:"category,omitempty"`;Risk string `json:"risk,omitempty"`;Recommendation string `json:"recommendation"`;AutomaticRepair bool `json:"automatic_repair"`;GuardianRequired bool `json:"guardian_required"`;DatabaseStatus string `json:"database_status"`}
func Classify(errorText,countryCode,language,repositoryRoot string)(Result,error){profile,err:=country.Resolve(countryCode,language);if err!=nil{return Result{},err};if strings.TrimSpace(errorText)==""||len(errorText)>8192{return Result{},errors.New("error_text must contain 1–8192 characters")};path:=filepath.Join(repositoryRoot,"core-zero","knowledge","worldwide_failure_db","patterns.json");raw,err:=os.ReadFile(path);if err!=nil{return Result{},errors.New("worldwide failure database unavailable; fail closed")};var db failureDB;if json.Unmarshal(raw,&db)!=nil||len(db.Patterns)==0{return Result{},errors.New("worldwide failure database invalid; fail closed")};lower:=strings.ToLower(errorText);out:=Result{Country:profile,Recommendation:"No curated pattern matched. Collect sanitized diagnostic evidence; do not guess a repair.",AutomaticRepair:false,GuardianRequired:true,DatabaseStatus:"loaded_curated_advisory"};for _,p:=range db.Patterns{for _,n:=range p.MatchAny{if n!=""&&strings.Contains(lower,strings.ToLower(n)){out.Matched=true;out.PatternID=p.ID;out.Category=p.Category;out.Risk=p.Risk;out.Recommendation=p.Recommendation;return out,nil}}};return out,nil}
